import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"DSP Platform — Response to “Stripe Integration Review” (Clarifications + What’s Fixed)","description":"","frontmatter":{},"headers":[],"relativePath":"CLIENT_RESPONSE_STRIPE_INTEGRATION_REVIEW.md","filePath":"CLIENT_RESPONSE_STRIPE_INTEGRATION_REVIEW.md"}'),n={name:"CLIENT_RESPONSE_STRIPE_INTEGRATION_REVIEW.md"};function r(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="dsp-platform-—-response-to-stripe-integration-review-clarifications-what-s-fixed" tabindex="-1">DSP Platform — Response to “Stripe Integration Review” (Clarifications + What’s Fixed) <a class="header-anchor" href="#dsp-platform-—-response-to-stripe-integration-review-clarifications-what-s-fixed" aria-label="Permalink to &quot;DSP Platform — Response to “Stripe Integration Review” (Clarifications + What’s Fixed)&quot;">​</a></h1><p>Hi team,</p><p>Thank you for the detailed review. Below is a point-by-point response to each item in your document, including what we have corrected, what is expected behavior in Stripe, and how to validate the system end-to-end.</p><hr><h2 id="part-1-—-stripe-issues" tabindex="-1">PART 1 — STRIPE ISSUES <a class="header-anchor" href="#part-1-—-stripe-issues" aria-label="Permalink to &quot;PART 1 — STRIPE ISSUES&quot;">​</a></h2><h2 id="_1-instructor-revenue-display-in-the-dsp-dashboard" tabindex="-1">1) Instructor revenue display in the DSP dashboard <a class="header-anchor" href="#_1-instructor-revenue-display-in-the-dsp-dashboard" aria-label="Permalink to &quot;1) Instructor revenue display in the DSP dashboard&quot;">​</a></h2><h3 id="what-was-happening" tabindex="-1">What was happening <a class="header-anchor" href="#what-was-happening" aria-label="Permalink to &quot;What was happening&quot;">​</a></h3><p>The instructor overview was showing <strong>gross</strong> revenue (full amount paid by the student) for “Money earned”.</p><h3 id="what-we-changed" tabindex="-1">What we changed <a class="header-anchor" href="#what-we-changed" aria-label="Permalink to &quot;What we changed&quot;">​</a></h3><p>We updated the instructor analytics calculation so “Money earned” reflects the <strong>instructor’s net earnings after DSP commission</strong> (i.e., the instructor share), matching the instructor’s transaction history.</p><h3 id="how-to-validate" tabindex="-1">How to validate <a class="header-anchor" href="#how-to-validate" aria-label="Permalink to &quot;How to validate&quot;">​</a></h3><ul><li><strong>Instructor Dashboard → Overview (“Money earned”)</strong> should now match:</li><li><strong>Instructor Dashboard → Transaction History → Total received</strong></li></ul><blockquote><p>Net earnings are derived from the stored split amounts (<code>instructorAmount</code>) per slot where available. For older/legacy records without that split field, the system falls back to a best-effort gross-per-slot calculation.</p></blockquote><hr><h2 id="_2-absence-of-commission-data-in-the-stripe-test-environment" tabindex="-1">2) “Absence of commission data” in the Stripe test environment <a class="header-anchor" href="#_2-absence-of-commission-data-in-the-stripe-test-environment" aria-label="Permalink to &quot;2) “Absence of commission data” in the Stripe test environment&quot;">​</a></h2><h3 id="key-truth-important" tabindex="-1">Key truth (important) <a class="header-anchor" href="#key-truth-important" aria-label="Permalink to &quot;Key truth (important)&quot;">​</a></h3><p>Stripe does <strong>not</strong> show a separate “DSP commission” transaction type or a dedicated “commission configuration” section for your platform.</p><p>In Stripe you will typically see:</p><ul><li><strong>Payments (gross)</strong>: the full lesson price paid by the student.</li><li><strong>Transfers to the instructor (net share)</strong>: the instructor’s portion (after DSP commission) sent to the instructor’s Connect account.</li></ul><p>The “commission” is the <strong>difference</strong> between the gross amount collected and the amount transferred to the instructor. Stripe does not label the retained difference as “commission”.</p><h3 id="where-commission-is-configured-source-of-truth" tabindex="-1">Where commission is configured (source of truth) <a class="header-anchor" href="#where-commission-is-configured-source-of-truth" aria-label="Permalink to &quot;Where commission is configured (source of truth)&quot;">​</a></h3><p>Commission is configured in the <strong>DSP Admin Dashboard</strong>, not in Stripe:</p><ul><li><strong>Admin Dashboard → Payment Management → Commission Management</strong><ul><li>You can set commission type (percentage or fixed amount) and the commission value.</li></ul></li></ul><h3 id="where-to-verify-commission-recommended" tabindex="-1">Where to verify commission (recommended) <a class="header-anchor" href="#where-to-verify-commission-recommended" aria-label="Permalink to &quot;Where to verify commission (recommended)&quot;">​</a></h3><p>Use the DSP dashboards:</p><ul><li><strong>Admin Dashboard → Payment Management → Transactions</strong><ul><li>You can verify platform gross receipts and platform commission entries per booking/slot.</li></ul></li><li><strong>Instructor Dashboard → Transaction History</strong><ul><li>Instructors see <strong>net amounts only</strong> (their share after commission).</li></ul></li><li><strong>Student Dashboard → Payment History</strong><ul><li>Students see what they paid (gross).</li></ul></li></ul><h3 id="stripe-side-verification-what-to-look-for" tabindex="-1">Stripe-side verification (what to look for) <a class="header-anchor" href="#stripe-side-verification-what-to-look-for" aria-label="Permalink to &quot;Stripe-side verification (what to look for)&quot;">​</a></h3><p>In Stripe Dashboard (test mode):</p><ul><li><strong>Payments</strong>: confirm the student payment exists (gross amount).</li><li><strong>Connect → Accounts → select the instructor</strong>: confirm the connected account exists and receives funds/transfer activity.</li><li>If you compare gross Payments vs Transfers to that instructor, the difference is the platform commission retained by DSP.</li></ul><p>We also created a dedicated guide with a checklist:</p><ul><li><code>docs/COMMISSION_AND_STRIPE_GUIDE.md</code></li></ul><hr><h2 id="_3-instructor-access-to-their-stripe-dashboard" tabindex="-1">3) Instructor access to their Stripe dashboard <a class="header-anchor" href="#_3-instructor-access-to-their-stripe-dashboard" aria-label="Permalink to &quot;3) Instructor access to their Stripe dashboard&quot;">​</a></h2><h3 id="what-was-happening-1" tabindex="-1">What was happening <a class="header-anchor" href="#what-was-happening-1" aria-label="Permalink to &quot;What was happening&quot;">​</a></h3><p>Instructors could connect Stripe (onboarding), but there was no option in DSP to open the instructor’s Stripe dashboard.</p><h3 id="what-we-changed-1" tabindex="-1">What we changed <a class="header-anchor" href="#what-we-changed-1" aria-label="Permalink to &quot;What we changed&quot;">​</a></h3><p>We added a secure “Open Stripe Dashboard” option for instructors to access their <strong>Stripe Express dashboard</strong>.</p><h3 id="what-stripe-dashboard-means-in-this-context" tabindex="-1">What “Stripe dashboard” means in this context <a class="header-anchor" href="#what-stripe-dashboard-means-in-this-context" aria-label="Permalink to &quot;What “Stripe dashboard” means in this context&quot;">​</a></h3><p>Instructors use <strong>Stripe Connect (Express)</strong>. Their Stripe interface is the <strong>Stripe Express dashboard</strong> for their connected account.</p><h3 id="where-instructors-can-access-stripe-now" tabindex="-1">Where instructors can access Stripe now <a class="header-anchor" href="#where-instructors-can-access-stripe-now" aria-label="Permalink to &quot;Where instructors can access Stripe now&quot;">​</a></h3><ul><li><strong>Instructor Settings → Payment Management</strong>: button <strong>“Open Stripe Dashboard”</strong></li><li><strong>Instructor Dashboard → Transaction History</strong>: button <strong>“Open Stripe Dashboard”</strong></li></ul><p>This allows instructors to:</p><ul><li>view earnings and balances</li><li>check payouts</li><li>monitor transactions related to lessons</li></ul><blockquote><p>Security note: the Stripe Express dashboard link is a short-lived, one-time link generated on demand. This is expected behavior per Stripe.</p></blockquote><hr><h2 id="_4-stripe-test-environment-not-displaying-transaction-data" tabindex="-1">4) Stripe test environment not displaying transaction data <a class="header-anchor" href="#_4-stripe-test-environment-not-displaying-transaction-data" aria-label="Permalink to &quot;4) Stripe test environment not displaying transaction data&quot;">​</a></h2><h3 id="what-s-expected-in-stripe-test-mode" tabindex="-1">What’s expected in Stripe test mode <a class="header-anchor" href="#what-s-expected-in-stripe-test-mode" aria-label="Permalink to &quot;What’s expected in Stripe test mode&quot;">​</a></h3><p>Stripe test mode should still show activity when you process payments through the DSP app, including:</p><ul><li>Payments created by Checkout / PaymentIntents</li><li>Connected accounts (Express) under Connect</li><li>Transfers to connected accounts (when created)</li></ul><h3 id="most-common-reasons-you-see-nothing-in-stripe" tabindex="-1">Most common reasons you “see nothing” in Stripe <a class="header-anchor" href="#most-common-reasons-you-see-nothing-in-stripe" aria-label="Permalink to &quot;Most common reasons you “see nothing” in Stripe&quot;">​</a></h3><p>Please verify the following before concluding the system is not connected:</p><ul><li><strong>Correct Stripe account</strong>: you are logged into the correct Stripe workspace (the platform account used by DSP).</li><li><strong>Correct mode</strong>: Stripe Dashboard is in <strong>Test mode</strong>, not Live (toggle in Stripe).</li><li><strong>Correct API keys in Render</strong>: <ul><li>Backend uses <code>sk_test_...</code> in test mode</li><li>Webhook secret corresponds to the test-mode webhook endpoint (Dashboard endpoint secret, not Stripe CLI secret)</li></ul></li><li><strong>Correct webhook endpoint (test mode)</strong>: <ul><li>Stripe Dashboard → Developers → Webhooks</li><li>Endpoint should point to your Render backend URL (e.g. <code>/webhooks/stripe</code>)</li><li>Events should show delivery attempts and 2xx responses from the server</li></ul></li></ul><h3 id="how-to-validate-quickly" tabindex="-1">How to validate quickly <a class="header-anchor" href="#how-to-validate-quickly" aria-label="Permalink to &quot;How to validate quickly&quot;">​</a></h3><ol><li>Make a new booking and complete payment with a test card.</li><li>In Stripe Dashboard (Test mode) check <strong>Payments</strong> → the payment should appear immediately.</li><li>In DSP Admin Dashboard check <strong>Payment Management → Transactions</strong> → records should appear immediately.</li></ol><p>If after this you still see no Stripe activity, it almost always means the environment is pointing to a different Stripe account/keys than the Dashboard you are checking.</p><hr><h2 id="_5-payment-redirection-during-student-checkout-why-student-goes-to-stripe" tabindex="-1">5) Payment redirection during student checkout (why student goes to Stripe) <a class="header-anchor" href="#_5-payment-redirection-during-student-checkout-why-student-goes-to-stripe" aria-label="Permalink to &quot;5) Payment redirection during student checkout (why student goes to Stripe)&quot;">​</a></h2><h3 id="why-the-student-is-redirected" tabindex="-1">Why the student is redirected <a class="header-anchor" href="#why-the-student-is-redirected" aria-label="Permalink to &quot;Why the student is redirected&quot;">​</a></h3><p>The student is redirected to <strong>Stripe Checkout</strong>, which is Stripe’s secure hosted payment page. We do this so Stripe can:</p><ul><li>securely collect card details (PCI compliant)</li><li>confirm payment</li><li>handle bank authentication flows (3D Secure / SCA) when required</li></ul><h3 id="the-student-does-not-create-a-stripe-account" tabindex="-1">The student does NOT create a Stripe account <a class="header-anchor" href="#the-student-does-not-create-a-stripe-account" aria-label="Permalink to &quot;The student does NOT create a Stripe account&quot;">​</a></h3><p>This redirection is <strong>not</strong> about creating or configuring a Stripe account. It is simply a Stripe-hosted payment page (like a normal e-commerce checkout).</p><h3 id="what-happens-during-that-step" tabindex="-1">What happens during that step <a class="header-anchor" href="#what-happens-during-that-step" aria-label="Permalink to &quot;What happens during that step&quot;">​</a></h3><ol><li>DSP creates a <strong>Stripe Checkout Session</strong> for the lesson.</li><li>The student is redirected to Stripe Checkout to pay.</li><li>After payment, Stripe redirects back to DSP (success/cancel URL).</li><li>DSP updates booking/payment status based on Stripe’s result.</li></ol><h3 id="is-this-part-of-3ds-authentication" tabindex="-1">Is this part of 3DS authentication? <a class="header-anchor" href="#is-this-part-of-3ds-authentication" aria-label="Permalink to &quot;Is this part of 3DS authentication?&quot;">​</a></h3><p><strong>Sometimes, yes.</strong></p><ul><li>If the card/bank requires <strong>3D Secure (SCA)</strong>, Stripe Checkout shows an authentication step during the payment flow.</li><li>If 3DS is not required, the student pays normally and returns to DSP.</li></ul><hr><h2 id="_6-pending-response-to-jacques-video-whatsapp" tabindex="-1">6) Pending response to Jacques’ video (WhatsApp) <a class="header-anchor" href="#_6-pending-response-to-jacques-video-whatsapp" aria-label="Permalink to &quot;6) Pending response to Jacques’ video (WhatsApp)&quot;">​</a></h2><p>We confirm the behavior shown (redirect to Stripe during checkout) is expected when using <strong>Stripe Checkout</strong>, and 3DS can appear inside that flow depending on the card/bank.</p><p>If you want us to respond line-by-line to the exact timestamps in Jacques’ video, please share:</p><ul><li>the timestamps you want explained, or</li><li>a short summary of what looks wrong.</li></ul><p>We will then map each point to the exact implemented flow (instant payment vs deferred/T‑48 vs 3DS-required cases).</p><hr><h2 id="part-2-—-pending-tasks-preventing-proper-platform-testing" tabindex="-1">PART 2 — PENDING TASKS PREVENTING PROPER PLATFORM TESTING <a class="header-anchor" href="#part-2-—-pending-tasks-preventing-proper-platform-testing" aria-label="Permalink to &quot;PART 2 — PENDING TASKS PREVENTING PROPER PLATFORM TESTING&quot;">​</a></h2><h3 id="what-we-can-confirm" tabindex="-1">What we can confirm <a class="header-anchor" href="#what-we-can-confirm" aria-label="Permalink to &quot;What we can confirm&quot;">​</a></h3><p>A correct completed/partial/pending matrix requires auditing against the actual ClickUp task list and the deployed environment, because the outcome depends on the exact task definitions and the reference environment.</p><h3 id="what-we-need-from-you" tabindex="-1">What we need from you <a class="header-anchor" href="#what-we-need-from-you" aria-label="Permalink to &quot;What we need from you&quot;">​</a></h3><p>Please share either:</p><ul><li>export/screenshots of both ClickUp sections, or</li><li>the ClickUp links + access permissions, and confirm which environment is the reference for the audit (Render demo vs local vs staging).</li></ul><h3 id="what-we-will-deliver" tabindex="-1">What we will deliver <a class="header-anchor" href="#what-we-will-deliver" aria-label="Permalink to &quot;What we will deliver&quot;">​</a></h3><p>For each task in both sections we will provide:</p><ul><li><strong>Status</strong>: Completed / Partially completed / Pending</li><li><strong>Where it is implemented</strong> (frontend pages + GraphQL + backend resolver/services)</li><li><strong>How to test it</strong></li><li><strong>If partial/pending</strong>: what remains and an estimate</li></ul><hr><h2 id="additional-note-—-t‐48-timing-render-vs-local" tabindex="-1">Additional note — T‑48 timing (Render vs local) <a class="header-anchor" href="#additional-note-—-t‐48-timing-render-vs-local" aria-label="Permalink to &quot;Additional note — T‑48 timing (Render vs local)&quot;">​</a></h2><h3 id="root-cause" tabindex="-1">Root cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root cause&quot;">​</a></h3><p>Previously, parts of the code used default JavaScript date parsing for slot start times. On Render the server timezone is typically <strong>UTC</strong>, which can shift the computed “T‑48” moment relative to Switzerland time.</p><h3 id="fix-applied" tabindex="-1">Fix applied <a class="header-anchor" href="#fix-applied" aria-label="Permalink to &quot;Fix applied&quot;">​</a></h3><p>We updated the T‑48 charge timing calculations and related checkout logic to interpret slot times in <code>SLOT_TIMEZONE</code> (e.g. <code>Europe/Zurich</code>) explicitly, so it behaves consistently regardless of server location or tester location.</p><h3 id="expected-behavior-after-fix" tabindex="-1">Expected behavior after fix <a class="header-anchor" href="#expected-behavior-after-fix" aria-label="Permalink to &quot;Expected behavior after fix&quot;">​</a></h3><p>T‑48 charging should occur at the correct “48 hours before lesson start” moment in Switzerland time, with only small delay possible due to the job interval (e.g., up to a few minutes depending on configuration).</p><hr><h2 id="recommended-next-validation-steps-fast" tabindex="-1">Recommended next validation steps (fast) <a class="header-anchor" href="#recommended-next-validation-steps-fast" aria-label="Permalink to &quot;Recommended next validation steps (fast)&quot;">​</a></h2><ol><li><strong>Commission validation</strong><ul><li>Set commission in Admin → Payment Management → Commission Management (e.g. 40%).</li><li>Make a test payment.</li><li>Verify Admin Transactions shows platform commission; Instructor Transactions show net.</li></ul></li><li><strong>Stripe visibility validation</strong><ul><li>Confirm Stripe Dashboard is in <strong>Test mode</strong> and you are viewing the same Stripe account used by the backend keys.</li><li>Check Stripe <strong>Payments</strong> after a booking payment.</li><li>Check the instructor’s Connect account exists under <strong>Connect → Accounts</strong>.</li></ul></li><li><strong>Instructor Stripe dashboard access</strong><ul><li>Instructor → Payment Management → “Open Stripe Dashboard”.</li><li>Confirm Stripe Express dashboard opens and shows connected-account financial data.</li></ul></li></ol><p>Thank you again — once we have the ClickUp task list access/export, we will provide the detailed implementation-status matrix requested in Part 2.</p>',95)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
